\journal{Journal of Hydrology}

\begin{document}

\begin{frontmatter}

\title{\textbackslash{}title\{Integrating Sentinel-2 Derived Surface Water Extent with USGS Discharge Measurements for Lake Oroville Monitoring\}}

% --- Author Information (Please Edit) ---
\author[1]{Your Name\corref{cor1}}
